import type { A1Module, Lesson } from "@/lib/course";

type P = [string, string, string];
type Q = [string, string[], number, string];
type Seed = { id:string; title:string; subtitle:string; objective:string; duration:number; focus:string; intro:string; phrases:P[]; grammarTitle:string; grammar:string; examples:[string,string][]; practice:Q[]; takeaway:string };
const lesson = (s:Seed):Lesson=>({id:s.id,slug:s.id,title:s.title,subtitle:s.subtitle,objective:s.objective,duration:s.duration,focus:s.focus,intro:s.intro,phrases:s.phrases.map(([english,portuguese,note])=>({english,portuguese,note})),grammar:{title:s.grammarTitle,explanation:s.grammar,examples:s.examples.map(([english,portuguese])=>({english,portuguese}))},practice:s.practice.map(([prompt,options,answer,explanation])=>({prompt,options,answer,explanation})),takeaway:s.takeaway});
const S=(id:string,title:string,subtitle:string,objective:string,duration:number,focus:string,intro:string,phrases:P[],grammarTitle:string,grammar:string,examples:[string,string][],practice:Q[],takeaway:string)=>lesson({id,title,subtitle,objective,duration,focus,intro,phrases,grammarTitle,grammar,examples,practice,takeaway});

export const a2ContinuationModules: A1Module[] = [
{ id:"stories-from-my-life",title:"Histórias da minha vida",subtitle:"Conte experiências passadas e fale de planos próximos.",lessons:[
S("a-special-day","A day to remember","Organize acontecimentos simples no passado.","Contar três acontecimentos de um dia especial usando passado simples e marcadores de sequência.",12,"Simple past e sequência narrativa","Uma comemoração, uma visita ou um passeio pode virar uma história curta. Organize o que aconteceu primeiro, depois e no final; escolha verbos no passado e mantenha os detalhes em uma ordem fácil de acompanhar.",[["Last Friday was special.","A sexta passada foi especial.","Last + período situa a história no passado."],["First, we met at the station.","Primeiro, nos encontramos na estação.","First apresenta o evento inicial."],["Then we had lunch together.","Depois, almoçamos juntos.","Then liga um evento ao próximo; had é passado de have."],["Finally, we watched the sunset.","Por fim, vimos o pôr do sol.","Finally marca o último evento; watched é passado regular." ]],"Marque a sequência e use o passado","Use simple past para eventos concluídos. Conecte eventos com first, then e finally. Verbos regulares recebem -ed; formas irregulares precisam ser aprendidas em contexto: have → had, meet → met, see → saw. Não é necessário usar conectores em todas as frases; eles servem para orientar quem escuta.",[["First, I packed my bag.","Primeiro, arrumei minha bolsa."],["Then we drove to the coast.","Depois, dirigimos até o litoral."],["We had dinner at seven.","Jantamos às sete."],["Finally, we came home.","Por fim, voltamos para casa."]],[["Qual conector apresenta o primeiro evento?",["First","Finally","Tomorrow"],0,"First sinaliza o começo da sequência."],["Complete: “We ___ dinner at seven.”",["had","have","has"],0,"Had é o passado irregular de have."],["Qual forma é o passado regular de visit?",["visited","visit","visiting"],0,"Visit é regular: acrescenta-se -ed."],["Que palavra combina com o encerramento da história?",["Finally","First","Next year"],0,"Finally apresenta o último passo ou evento." ]],"Last ____ was special. First, I ____. Then, we ____. Finally, ____.") ,
S("childhood-memories","When I was younger","Compare uma lembrança antiga com sua vida atual.","Relatar uma lembrança simples da infância e contrastá-la com um hábito atual usando used to em reconhecimento e produção guiada.",13,"Past be, past simple e used to","Fotos antigas podem trazer lembranças de lugares, brincadeiras e rotinas. Nesta aula você vai contar algo que era comum antes e comparar com o presente, sem presumir que todas as infâncias são iguais.",[["When I was younger, I lived near the sea.","Quando eu era mais jovem, morava perto do mar.","Was é passado de be; lived é passado regular."],["I used to ride my bike after school.","Eu costumava andar de bicicleta depois da escola.","Used to descreve um hábito passado que não é necessariamente atual."],["My brother was very curious.","Meu irmão era muito curioso.","Was acompanha I/he/she/it; were acompanha you/we/they."],["Now I usually walk to work.","Agora geralmente vou a pé ao trabalho.","Now e usually ajudam a marcar uma rotina atual." ]],"Lembranças passadas e hábitos atuais","Use was/were para estados no passado e simple past para eventos concluídos. Used to + verbo base descreve hábitos ou estados que eram comuns antes: I used to play. Para contrastar, use but now + simple present. A forma usada aqui é afirmativa; não confunda com be used to, que tem outro significado e construção.",[["We were neighbors when we were children.","Éramos vizinhos quando éramos crianças."],["She used to visit her grandparents every Sunday.","Ela costumava visitar os avós todo domingo."],["I used to have long hair, but now it’s short.","Eu costumava ter cabelo comprido, mas agora é curto."],["They played outside after school.","Eles brincavam lá fora depois da escola." ]],[["Complete: “When I was six, I ___ in Recife.”",["lived","live","am living"],0,"Um período passado concluído pede lived."],["Used to é usado aqui para:",["um hábito passado","um plano para amanhã","uma ação neste exato momento"],0,"Used to descreve costume ou estado anterior."],["Qual frase contrasta passado e presente?",["I used to cycle, but now I take the bus.","I use to cycled tomorrow.","I was cycle but now bus."],0,"Used to + base e but now + presente fazem contraste."],["Qual sujeito combina com were?",["They","She","He"],0,"Were acompanha you/we/they; was acompanha I/he/she/it." ]],"When I was younger, I used to ____. Now I usually ____, but ____.") ,
S("past-questions","What happened?","Faça perguntas básicas sobre eventos passados.","Fazer perguntas e responder sobre um evento passado usando did + verbo base e perguntas com was/were.",12,"Perguntas no passado com did e be","Uma amiga chega contando que perdeu o ônibus. Você pode demonstrar interesse e pedir detalhes sem transformar a conversa em interrogatório. Repare no auxiliar e no verbo que vem depois dele.",[["What happened?","O que aconteceu?","Happened já é passado; a pergunta usa o verbo sem did."],["Where did you wait?","Onde você esperou?","Did marca o passado; wait fica na forma base."],["Did the bus arrive?","O ônibus chegou?","Pergunta de sim/não: did + sujeito + verbo base."],["Were you alone?","Você estava sozinho(a)?","Com be no passado, invertemos was/were e o sujeito; não usamos did." ]],"Did + verbo base; was/were sem did","Para verbos de ação, forme perguntas com question word + did + sujeito + verbo base: What did you see? Para sim/não: Did you call? Em respostas, retome did/didn’t. Com be, use was/were diretamente: Where were you? Evite a forma dupla *Did you went?*.",[["When did they leave?","Quando eles foram embora?"],["Did Ana call you? Yes, she did.","Ana ligou para você? Sim."],["Why was the shop closed?","Por que a loja estava fechada?"],["Were you at the station? No, I wasn’t.","Você estava na estação? Não." ]],[["Complete: “Where ___ he go?”",["did","was","does"],0,"Pergunta passada de ação usa did + sujeito + verbo base."],["Após did, escolha:",["see","saw","seen"],0,"Did já marca o passado; o verbo volta à forma base."],["Qual pergunta usa be corretamente?",["Were they tired?","Did they were tired?","Was they tired?"],0,"Com they, use were diretamente, sem did."],["Resposta curta a “Did you call?”",["No, I didn’t.","No, I wasn’t.","No, I don’t did."],0,"A resposta curta retoma o auxiliar did." ]],"What happened? Where did ____? Were you ____? Yes, I was / No, I wasn’t.") ,
S("stories-review","A little story","Una eventos e marcadores de tempo em uma narrativa curta.","Recontar uma história de quatro eventos usando passado simples, marcadores de tempo e conectores de sequência.",14,"Revisão de narrativa no passado","A revisão reúne eventos concluídos, perguntas e conectores. Imagine uma pequena mudança de planos durante um passeio; conte o que estava previsto, o que aconteceu e como terminou. Uma narrativa clara vale mais do que uma lista longa de frases.",[["Yesterday morning, we planned a picnic.","Ontem de manhã, planejamos um piquenique.","Yesterday situa toda a ação no passado."],["At first, the weather was sunny.","No começo, o tempo estava ensolarado.","At first apresenta a situação inicial."],["Then it started to rain.","Depois começou a chover.","Started é regular; rain pode ser usado como verbo."],["In the end, we ate at a café.","No fim, comemos em um café.","In the end resume o resultado da sequência." ]],"Estruture uma narrativa com início, mudança e resultado","Use marcadores como yesterday, last week e on Sunday. Conecte fatos com at first, then, after that e in the end. Mantenha os verbos no passado para ações concluídas; em perguntas com did, use o verbo base. Se uma palavra estiver faltando, prefira uma frase simples que você domina.",[["Last month, we visited a small town.","No mês passado, visitamos uma cidade pequena."],["After that, we found a quiet café.","Depois disso, encontramos um café tranquilo."],["It was cold, so we went inside.","Estava frio, então entramos."],["In the end, everyone had a good time.","No fim, todos se divertiram." ]],[["Qual frase situa a história no passado?",["Last month, we visited a small town.","Next month, we visit a small town.","Every month, we visit a small town."],0,"Last month é período passado concluído e visited está no passado."],["Complete: “After that, we ___ a café.”",["found","find","did found"],0,"A afirmativa passada usa found, passado irregular de find."],["Qual pergunta está correta?",["What did you eat?","What did you ate?","What you ate?"],0,"Did + sujeito + verbo base eat forma a pergunta."],["Qual expressão introduz o resultado final?",["In the end","At first","Next year"],0,"In the end destaca o resultado ou conclusão." ]],"Yesterday/Last ____, I ____. At first ____. Then ____. In the end ____.")
]},
{ id:"everyday-independence",title:"Mais autonomia no dia a dia",subtitle:"Resolva situações de serviço, compras, saúde e deslocamento.",lessons:[
S("plans-for-next-month","Plans for next month","Explique planos usando going to.","Descrever dois planos definidos para o próximo mês e perguntar sobre os planos de outra pessoa.",12,"Going to para planos e intenções","Um calendário ajuda a transformar ideias em planos. Pratique como dizer o que pretende fazer, indicar quando e perguntar sobre a intenção de outra pessoa, deixando espaço para mudanças.",[["I’m going to visit my aunt next month.","Vou visitar minha tia no próximo mês.","Be going to + verbo base expressa plano/intenção."],["We’re going to take a short course.","Vamos fazer um curso curto.","We’re = we are; take fica na forma base."],["Are you going to travel in July?","Você vai viajar em julho?","Be vem antes do sujeito na pergunta."],["I’m not going to move this year.","Não vou me mudar este ano.","Negativa: be + not + going to + verbo." ]],"Planos futuros com be going to","Use am/is/are + going to + verbo base para planos e intenções: She’s going to study. Na negativa, coloque not após be. Na pergunta, inverta be e sujeito: Are they going to come? Marcadores como next month e this weekend situam o plano. Will e going to não são sempre intercambiáveis; aqui foque em intenção planejada.",[["He’s going to start a new job.","Ele vai começar um trabalho novo."],["What are you going to do this weekend?","O que você vai fazer neste fim de semana?"],["They aren’t going to drive.","Eles não vão dirigir."],["Is Mia going to join the class?","Mia vai participar da aula?"]],[["Complete: “I ___ going to call her.”",["am","is","are"],0,"I combina com am."],["Após going to, use:",["verbo base","verbo com -ed","verbo com -ing"],0,"A estrutura é going to + forma base."],["Qual pergunta está correta?",["Are you going to study?","Do you going to study?","Are you go to study?"],0,"Pergunta: are + sujeito + going to + verbo base."],["Qual frase descreve um plano negativo?",["We aren’t going to stay home.","We don’t going to stay home.","We aren’t go stay home."],0,"Negue com be + not antes de going to." ]],"Next month, I’m going to ____. Are you going to ____? We aren’t going to ____.") ,
S("travel-experiences","Have you been there?","Pergunte sobre experiências de viagem.","Perguntar se alguém já visitou um lugar e responder com present perfect e detalhe específico em simple past.",13,"Present perfect: ever/never e simple past com tempo definido","Duas pessoas conversam sobre lugares que já conheceram. Primeiro descubra se a experiência aconteceu alguma vez; depois pergunte quando ou onde, se a pessoa quiser contar mais.",[["Have you ever been to Peru?","Você já esteve no Peru?","Ever em pergunta sobre experiência de vida até agora."],["Yes, I have. I went in 2023.","Sim. Fui em 2023.","Present perfect responde à experiência; simple past dá tempo definido."],["I’ve never travelled alone.","Nunca viajei sozinha(o).","Never significa nunca e combina com afirmativa gramatical; evite dupla negativa."],["What was your favorite place?","Qual foi seu lugar favorito?","Was pergunta por detalhe específico no passado." ]],"Experiência sem data: present perfect","Use have/has + past participle para experiências até agora: Have you ever been…? Responda Yes, I have / No, I haven’t. Never já carrega sentido negativo. Quando mencionar um período concluído ou data específica, use simple past: I went in 2023. Compare *Have you been?* (experiência) com *When did you go?* (tempo definido).",[["Has Leo ever visited Chile?","Leo já visitou o Chile alguma vez?"],["I’ve never flown on a plane.","Nunca viajei de avião."],["We went to Lisbon last spring.","Fomos a Lisboa na primavera passada."],["Have they tried local food?","Eles já experimentaram comida local?"]],[["Complete: “Have you ever ___ to Canada?”",["been","went","be"],0,"Present perfect usa past participle been."],["Qual resposta indica nenhuma experiência?",["No, I haven’t.","No, I didn’t ever have.","No, I haven’t never."],0,"No, I haven’t é a resposta curta correta, sem dupla negativa."],["Ao acrescentar “in 2022”, escolha:",["I travelled in 2022.","I have travelled in 2022.","I have travel in 2022."],0,"Ano específico concluído pede simple past."],["Ever geralmente aparece aqui em:",["perguntas sobre experiências","ordens","perguntas de preço"],0,"Have you ever…? pergunta se a experiência ocorreu alguma vez." ]],"Have you ever ____? Yes, I have / No, I haven’t. I ____ in ____.") ,
S("making-arrangements","Let’s make a plan","Combine datas, horários e atividades.","Negociar um encontro combinando atividade, horário e alternativa com expressões de sugestão e disponibilidade.",12,"Sugestões e combinações com How about / works for me","Organizar um encontro exige mais do que escolher uma atividade: também é preciso achar um horário conveniente para todos. Pratique propor, aceitar com ressalvas e sugerir uma alternativa de modo colaborativo.",[["How about meeting on Saturday?","Que tal nos encontrarmos no sábado?","How about + verbo em -ing faz sugestão."],["Does 3 p.m. work for you?","Às 15h funciona para você?","Work for someone significa ser conveniente."],["Saturday works for me.","Sábado funciona para mim.","Works for me aceita uma proposta."],["Could we meet a little later?","Poderíamos nos encontrar um pouco mais tarde?","Could we + verbo base é uma sugestão/pedido cortês." ]],"Sugira e negocie horário","Use How about + substantivo/verbo em -ing? para sugerir. Use Does + horário + work for you? para checar disponibilidade; a resposta afirmativa é The time works for me. Use Could we…? ou Can we…? para propor ajuste. Com on, mencione o dia; com at, o horário.",[["How about having lunch on Friday?","Que tal almoçarmos na sexta?"],["Does 10 a.m. work for you?","Às 10h funciona para você?"],["Could we meet at the library?","Poderíamos nos encontrar na biblioteca?"],["I’m free after six.","Estou livre depois das seis." ]],[["Complete: “How about ___ a film?”",["watching","watch","to watch"],0,"Após How about, use substantivo ou verbo em -ing."],["Como perguntar se 4 p.m. é conveniente?",["Does 4 p.m. work for you?","Do 4 p.m. works you?","Is work 4 p.m. you?"],0,"Does + horário singular + verbo base work + for you."],["Qual frase sugere mudar o horário educadamente?",["Could we meet a little later?","We meet later you must.","Could we to meet later?"],0,"Could we + forma base é uma proposta cortês."],["Qual preposição acompanha Saturday?",["on","at","in"],0,"Use on com dias da semana." ]],"How about ____? Does ____ work for you? Could we meet at ____ instead?") ,
S("what-i-have-done","Things I’ve tried","Introduza experiências com present perfect em situações comuns.","Falar de experiências usando present perfect com just/already/yet em contextos cotidianos.",13,"Present perfect com just, already e yet","Uma amiga conta atividades recentes que tentou pela primeira vez. Veja como just, already e yet mudam o foco da conversa sem exigir uma data exata, e como o simple past entra quando contamos quando aconteceu.",[["I’ve just tried sushi.","Acabei de experimentar sushi.","Just costuma vir entre have/has e o particípio."],["She’s already booked the tickets.","Ela já reservou as passagens.","Already enfatiza que algo aconteceu antes do esperado ou até agora."],["Have you finished yet?","Você já terminou?","Yet aparece frequentemente no final de pergunta."],["I tried it last month.","Experimentei no mês passado.","Last month é período concluído: use simple past." ]],"Just/already/yet com present perfect","Forme present perfect com have/has + past participle. Just indica algo muito recente; already, algo que já ocorreu; yet costuma aparecer no fim de perguntas e negativas. Com tempo passado específico (yesterday, last month), use simple past. Em inglês britânico e americano há diferenças de preferência em alguns contextos; ambas as formas podem ser naturais conforme a variedade.",[["We’ve just arrived.","Acabamos de chegar."],["He has already seen that film.","Ele já viu aquele filme."],["They haven’t called yet.","Eles ainda não ligaram."],["Have you eaten yet?","Você já comeu?" ]],[["Complete: “I’ve ___ finished my homework.”",["just","yesterday","last"],0,"Just pode vir entre have e particípio para algo recente."],["Yet normalmente fica no fim de:",["perguntas e negativas","afirmações com data definida","ordens"],0,"Have you finished yet? / I haven’t finished yet."],["“She already booked the room” foca que:",["a reserva já aconteceu","a reserva acontecerá amanhã","ninguém reservou"],0,"Already indica que a ação já ocorreu."],["Com “two days ago”, use:",["simple past","present perfect","going to"],0,"Two days ago determina tempo passado concluído." ]],"I’ve just ____. I’ve already ____. I haven’t ____ yet. I ____ two days ago.") ,
S("my-life-so-far","A story so far","Conecte experiências passadas a planos futuros.","Apresentar uma breve trajetória com duas experiências e um plano, distinguindo present perfect sem data de simple past datado e going to.",14,"Present perfect, simple past e going to","Uma pequena apresentação pode conectar experiências que você já teve, acontecimentos específicos e o que pretende fazer a seguir. Escolha o tempo verbal de acordo com o tipo de informação, não apenas porque a frase parece estar no passado.",[["I’ve learned English for two years.","Estudo inglês há dois anos.","Present perfect com for liga período iniciado no passado ao presente."],["I started classes in 2024.","Comecei as aulas em 2024.","Ano definido pede simple past."],["I’ve visited two countries.","Já visitei dois países.","Experiência sem data específica até agora."],["Next year, I’m going to study abroad.","No próximo ano, vou estudar fora.","Going to expressa plano/intenção." ]],"Escolha o tempo pelo significado","Present perfect (have/has + particípio) conecta experiência ou período ao presente quando o momento exato não é foco. Simple past situa evento num período concluído e definido. Going to apresenta plano/intenção futura. For mede duração; since indica ponto inicial. Não combine present perfect com yesterday/last year para a mesma ação concluída.",[["She has worked here for six months.","Ela trabalha aqui há seis meses."],["She started this job in January.","Ela começou neste trabalho em janeiro."],["Have you ever studied online?","Você já estudou on-line?"],["We’re going to take a language test next spring.","Vamos fazer um teste de idioma na próxima primavera." ]],[["Complete: “I ___ this book last week.”",["read","have read","have reading"],0,"Last week é período concluído; simple past read (mesma forma escrita)."],["Qual pergunta explora experiência até agora?",["Have you ever travelled alone?","Did you ever travel tomorrow?","Are you travel alone?"],0,"Present perfect pergunta sobre experiência sem data definida."],["Complete: “They ___ going to move next year.”",["are","is","do"],0,"They combina com are + going to."],["Since normalmente acompanha:",["ponto inicial","duração numérica","verbo no infinitivo"],0,"Since 2021 aponta o início; for three years indica duração." ]],"So far, I’ve ____. In ____, I ____. I’ve ____ for/since ____. Next, I’m going to ____.")
]},
{ id:"people-community",title:"Pessoas e comunidade",subtitle:"Descreva relações, lugares e acontecimentos de sua comunidade.",lessons:[
S("finding-the-right-size","Does it fit?","Pergunte sobre tamanhos e ajuste de roupas.","Perguntar e responder sobre tamanho, cor e ajuste ao experimentar uma peça.",11,"Tamanhos, demonstrativos e fit","Em uma loja, medidas variam entre marcas e países. Aprenda a perguntar pelo tamanho e pelo ajuste, confirmando a etiqueta da peça em vez de supor uma equivalência universal.",[["Do you have this in a larger size?","Você tem esta peça em um tamanho maior?","Larger é comparativo de large."],["It’s a little too tight.","Está um pouco apertada demais.","Too + adjetivo expressa excesso; a little suaviza."],["Does this jacket fit?","Esta jaqueta serve?","Fit aqui significa ter o ajuste/tamanho adequado."],["Could I try it on?","Posso experimentar?","Try on é verbo frasal; pronome fica entre try e on." ]],"Comparar tamanhos e falar de ajuste","Use this/these para apontar peça(s) próximas. Use comparativo + than para comparação explícita: larger than this one. Too + adjetivo significa mais do que desejado; not … enough significa insuficiente. Try on significa experimentar uma roupa: try it on.",[["These shoes are too small.","Estes sapatos são pequenos demais."],["Do you have a smaller one?","Você tem um menor?"],["This coat is warmer than that one.","Este casaco é mais quente que aquele."],["The sleeves aren’t long enough.","As mangas não são compridas o bastante." ]],[["Complete: “Could I try ___ on?”",["it","on it","to it"],0,"Com pronome, try it on: o pronome fica entre verbo e partícula."],["Too tight significa:",["apertada demais","comprida o bastante","mais larga que outra"],0,"Too indica excesso; tight é apertado."],["Qual pergunta solicita outra numeração?",["Do you have this in a larger size?","Do you larger this size have?","Are you have a size larger?"],0,"Do you have…? pergunta disponibilidade de outro tamanho."],["Qual frase usa comparativo correto?",["This one is smaller than that one.","This one is more small that one.","This one smaller that one than."],0,"Small forma o comparativo regular smaller + than." ]],"Does it fit? It’s too ____. Do you have a ____ one? Could I try it on?") ,
S("returns-and-receipts","Can I return this?","Converse sobre recibos e trocas simples.","Explicar um problema simples com uma compra, apresentar recibo e perguntar sobre a política de troca/devolução.",12,"Can I…? e perguntas sobre compras","Uma compra pode não servir ou apresentar um defeito. Pratique como explicar o motivo, perguntar quais opções existem e confirmar a política da loja; regras de devolução variam e precisam ser verificadas no local.",[["I bought this yesterday.","Comprei isto ontem.","Bought é passado irregular de buy."],["Can I return it?","Posso devolver?","Can I + verbo base pede permissão/informação."],["Here’s the receipt.","Aqui está o recibo.","Here’s = here is; receipt é comprovante/recibo."],["Could I exchange it for a larger size?","Poderia trocar por um tamanho maior?","Exchange … for … significa trocar uma coisa por outra." ]],"Explicar uma compra e perguntar opções","Use simple past para compra concluída: I bought it yesterday. Pergunte Can I return/exchange it?; a resposta depende da política vigente da loja. It aponta para o item. Use for para especificar a troca: exchange it for a different size. Peça confirmação de prazo e condições.",[["I paid by card.","Paguei com cartão."],["The zipper is broken.","O zíper está quebrado."],["Can I exchange these shoes for a smaller size?","Posso trocar estes sapatos por um número menor?"],["How many days do I have to return it?","Quantos dias tenho para devolver?" ]],[["Bought é passado de:",["buy","bring","bringed"],0,"Buy é irregular: buy → bought."],["Qual pergunta pede uma troca?",["Can I exchange it for another size?","Can I exchanged it another size?","Do I exchange for it another?"],0,"Após can, use verbo base exchange."],["O que significa receipt?",["Recibo/comprovante","Provador","Desconto"],0,"Receipt é o comprovante de compra."],["Qual atitude é adequada em uma loja?",["Perguntar e conferir a política de devolução.","Assumir que toda loja aceita devolução sem condições.","Entregar dados bancários desnecessários."],0,"Políticas variam; pergunte e confirme os termos." ]],"I bought ____ yesterday. Here’s the receipt. Can I return/exchange it for ____?") ,
S("at-the-post-office","Sending a package","Peça informações sobre envio e entrega.","Solicitar opções básicas de envio, informar destino e perguntar sobre prazo e acompanhamento.",12,"Perguntas sobre serviço postal","Você precisa enviar um pacote e quer entender as opções disponíveis. Pratique explicar o destino, perguntar por preço e prazo e solicitar informações de rastreamento; tarifas e prazos dependem do serviço escolhido.",[["I’d like to send this package to Canada.","Gostaria de enviar este pacote para o Canadá.","I’d like to + verbo base faz um pedido educado."],["How long does delivery take?","Quanto tempo a entrega leva?","How long pergunta duração; does + take."],["Can I track the package?","Posso rastrear o pacote?","Track é acompanhar/rastrear uma encomenda."],["Is there a cheaper option?","Existe uma opção mais barata?","Cheaper é comparativo de cheap." ]],"Pergunte por serviço, prazo e custo","Use I’d like to + verbo para solicitar serviço. Pergunte How much does it cost? para preço e How long does it take? para duração. Com he/she/it, perguntas usam does + verbo base. Peça ao atendente que explique opções; preço e prazo devem ser confirmados na agência.",[["Where can I buy a padded envelope?","Onde posso comprar um envelope acolchoado?"],["Does this service include tracking?","Este serviço inclui rastreamento?"],["I need to fill in this form.","Preciso preencher este formulário."],["When will the package arrive?","Quando o pacote vai chegar?" ]],[["Pergunte quanto custa:",["How much does it cost?","How many does it cost?","How much it costs does?"],0,"How much + does + sujeito + verbo base pergunta preço."],["Complete: “How long does delivery ___?”",["take","takes","took"],0,"Após does, use verbo base take."],["Track a package significa:",["Rastrear uma encomenda.","Empacotar um presente.","Pagar em dinheiro."],0,"Track significa acompanhar o percurso."],["Cheaper é comparativo de:",["cheap","cheaply","the cheap"],0,"Adjetivo curto cheap forma cheaper." ]],"I’d like to send ____ to ____. How much does ____ cost? How long does it take?") ,
S("booking-an-appointment","A time that works","Marque um compromisso e proponha outro horário.","Marcar compromisso, confirmar data/horário e propor alternativa com linguagem cortês.",12,"Convites, horários e disponibilidade","Ao marcar uma consulta ou serviço, você precisa indicar quando pode e confirmar os detalhes. Aprenda a oferecer dois horários, dizer que um não funciona e combinar uma alternativa sem compartilhar informações além do necessário.",[["I’d like to make an appointment.","Gostaria de marcar um horário.","Make an appointment é combinação comum."],["Are you available on Tuesday morning?","Você tem disponibilidade na terça de manhã?","Available significa disponível."],["I’m afraid I can’t make it at ten.","Infelizmente não consigo às dez.","I’m afraid suaviza uma notícia negativa."],["Would two o’clock work instead?","Duas horas funcionaria no lugar?","Would…work? checa disponibilidade de forma cordial." ]],"Ofereça e confirme horários","Use I’d like to make/book an appointment para iniciar. Pergunte Are you available…? ou Does … work for you? Para alternativa, Would + horário + work instead? Use on com dias e at com horários. Confirme data, fuso/local se remoto e detalhes essenciais antes de encerrar.",[["Could we book it for Thursday afternoon?","Podemos marcar para quinta à tarde?"],["I’m free after 2 p.m.","Estou livre depois das 14h."],["That time works for me.","Esse horário funciona para mim."],["Could you confirm the date, please?","Poderia confirmar a data, por favor?" ]],[["Qual expressão inicia um agendamento?",["I’d like to make an appointment.","I like appointment make.","I’d appointment making."],0,"Make an appointment é a combinação natural."],["Pergunte disponibilidade na terça:",["Are you available on Tuesday?","Do you available Tuesday?","Are available you at Tuesday?"],0,"Be + sujeito + available forma a pergunta; on acompanha o dia."],["Como oferecer alternativa educadamente?",["Would two o’clock work instead?","Two o’clock works you instead?","Would work two o’clock you?"],0,"Would…work? verifica se a alternativa convém."],["Qual preposição acompanha horário exato?",["at","on","in"],0,"Use at com horário, como at ten o’clock." ]],"I’d like to book ____. Are you available on ____? Would ____ work instead?") ,
S("services-review","Getting things done","Pratique pequenas conversas para resolver tarefas.","Completar uma sequência curta de serviço: apresentar necessidade, perguntar opções, confirmar horário e agradecer.",13,"Revisão de serviços e pedidos","A autonomia cresce quando você consegue resolver pequenas tarefas em inglês. Nesta revisão, combine frases para uma compra, envio ou agendamento, escolhendo o registro cortês e confirmando informações importantes.",[["I’m here to collect a package.","Estou aqui para retirar uma encomenda.","Collect é retirar/pegar algo disponível."],["Could you explain the options?","Poderia explicar as opções?","Could you + verbo base faz pedido cortês."],["Does the earlier time work?","O horário mais cedo funciona?","Earlier é comparativo de early."],["Thank you for your help.","Obrigado(a) pela ajuda.","Uma forma simples de encerrar a interação." ]],"Use linguagem clara para resolver uma tarefa","Abra com I’m here to… ou I’d like to…; faça perguntas com could, can ou do/does conforme a estrutura; confirme com So, that’s…? Para horários definidos, at; para dias, on. Repita dados importantes como data, custo ou local para confirmar entendimento.",[["I’m here to return this item.","Estou aqui para devolver este item."],["Could you tell me how much it costs?","Poderia me dizer quanto custa?"],["So, the appointment is at 3 p.m. on Friday?","Então, o compromisso é sexta às 15h?"],["That option is better for me.","Essa opção é melhor para mim." ]],[["Qual abertura explica a razão da visita?",["I’m here to collect a package.","I here collect package am.","I was here package tomorrow."],0,"I’m here to + verbo explica o propósito atual."],["Complete: “Could you ___ the options?”",["explain","explains","to explain"],0,"Após could, use verbo base."],["Combine preposições corretamente:",["at 3 p.m. on Friday","on 3 p.m. at Friday","in 3 p.m. in Friday"],0,"At acompanha horário; on acompanha dia."],["Como confirmar um detalhe antes de sair?",["So, that’s at 3 p.m., right?","You are 3 at what?","I no ask detail."],0,"So…right? checa entendimento de forma natural." ]],"I’m here to ____. Could you ____? So, that’s ____ on/at ____? Thank you.") ,
S("something-is-wrong","There’s a problem","Descreva um problema simples com um serviço ou objeto.","Relatar um problema cotidiano, dizer quando começou e solicitar uma solução ou próximo passo.",12,"There is, simple past e pedidos de solução","Um objeto parou de funcionar ou uma entrega não chegou. Descreva o fato observável, indique quando aconteceu e pergunte qual é o próximo passo, sem presumir a causa.",[["There’s a problem with my order.","Há um problema com meu pedido.","There’s = there is; with identifica o item relacionado."],["The screen stopped working yesterday.","A tela parou de funcionar ontem.","Stopped é passado regular; yesterday marca tempo concluído."],["I haven’t received the package yet.","Ainda não recebi o pacote.","Present perfect + yet indica algo esperado que não ocorreu até agora."],["Could you check it, please?","Poderia verificar, por favor?","Could you + verbo base pede uma ação." ]],"Descrever fatos e pedir o próximo passo","Use There is/There’s + problema + with + item. Para evento concluído em horário definido, use simple past. Para algo que ainda não aconteceu até agora, present perfect + yet é comum: I haven’t received it yet. Peça assistência com Could you check…? e forneça apenas dados necessários ao serviço.",[["There’s a mistake on the receipt.","Há um erro no recibo."],["The printer stopped yesterday.","A impressora parou ontem."],["We haven’t heard back yet.","Ainda não recebemos resposta."],["Could you tell me what happens next?","Poderia me dizer o que acontece agora?" ]],[["Complete: “There ___ a problem with the ticket.”",["is","are","do"],0,"A problem é singular: there is."],["Yesterday requer nesta frase:",["The phone stopped working.","The phone has stop working.","The phone stop working."],0,"Yesterday marca passado concluído; stopped é simple past."],["Yet em “I haven’t received it yet” indica:",["ainda não aconteceu até agora","aconteceu amanhã","acontece sempre"],0,"Present perfect negativo + yet descreve expectativa não cumprida até agora."],["Qual pedido é claro e educado?",["Could you check the order, please?","Check order now you.","Could check to order?"],0,"Could you + verbo base + please é cortês." ]],"There’s a problem with ____. It happened ____ / I haven’t ____ yet. Could you ____?") ,
S("at-the-doctors","A doctor’s appointment","Explique sintomas básicos e responda perguntas.","Comunicar há quanto tempo sente uma condição simples e responder perguntas básicas em consulta, procurando atendimento profissional.",13,"Symptoms, feel/have e duração","Esta aula é prática de idioma, não orientação médica. Você aprenderá a descrever em inglês o que sente, quando começou e pedir que o profissional explique algo novamente; diagnóstico e tratamento cabem a profissionais de saúde.",[["I’ve had a headache since this morning.","Estou com dor de cabeça desde esta manhã.","Present perfect com since marca início que continua até agora."],["I feel dizzy when I stand up.","Sinto tontura quando me levanto.","Feel + adjetivo descreve sensação; when introduz circunstância."],["How long have you felt this way?","Há quanto tempo você se sente assim?","How long pergunta duração até agora."],["Could you explain that more slowly?","Poderia explicar isso mais devagar?","Pedido de esclarecimento cortês." ]],"Descrever sensação e duração","Use I have a… para certas dores (a headache) e I feel + adjetivo (dizzy, tired). How long have you had/felt…? usa present perfect para duração até o presente; responda com for + período ou since + início. Relate fatos com precisão e peça interpretação ao profissional, sem se autodiagnosticar.",[["I’ve had this cough for three days.","Estou com esta tosse há três dias."],["The pain started last night.","A dor começou ontem à noite."],["I feel sick after eating.","Sinto enjoo depois de comer."],["Could you write the instructions down?","Poderia anotar as instruções?" ]],[["Qual frase diz há quanto tempo tem tosse?",["I’ve had a cough for three days.","I have cough since three days ago for.","I had have cough three days."],0,"Have had + for + duração liga o sintoma ao presente."],["Complete: “The pain ___ last night.”",["started","has start","start"],0,"Last night é tempo definido concluído: simple past started."],["Since acompanha melhor:",["since Monday","since three hours","since a long time"],0,"Since indica ponto inicial; for indica duração."],["Esta prática substitui consulta?",["Não; ensina frases e incentiva procurar profissional.","Sim, fornece diagnóstico.","Sim, recomenda tratamento."],0,"É uma atividade linguística, não orientação clínica." ]],"I’ve had/felt ____ for/since ____. It started ____. Could you explain ____?") ,
S("directions-in-detail","Around the neighborhood","Compreenda instruções de percurso mais completas.","Pedir e seguir um percurso com dois marcos e instruções de virar/seguir em frente.",12,"Imperativos, marcos e sequência espacial","Você está perto de uma praça e precisa encontrar a biblioteca. Peça uma rota, escute as instruções em etapas e confirme o marco principal antes de seguir.",[["Go straight past the bank.","Siga em frente passando pelo banco.","Go straight é instrução; past indica passar além de um marco."],["Turn left at the traffic lights.","Vire à esquerda no semáforo.","At indica o ponto de referência onde virar."],["It’s across from the library.","Fica em frente à biblioteca.","Across from indica do outro lado/em frente."],["Is it far from here?","É longe daqui?","Far from pergunta distância." ]],"Dê instruções em etapas","Use imperativo com verbo base para instruções: go, turn, cross. Organize com first, then e after that. Use at + marco para o ponto de ação, past para passar por um lugar, across from para localização oposta e between A and B para posição. Confirme a rota com pergunta curta se necessário.",[["First, cross the bridge.","Primeiro, atravesse a ponte."],["Then turn right at the pharmacy.","Depois vire à direita na farmácia."],["The café is between the bank and the park.","O café fica entre o banco e o parque."],["Walk past the school; the station is on your left.","Passe pela escola; a estação fica à sua esquerda." ]],[["Qual instrução está no imperativo correto?",["Turn left at the corner.","Turns left at the corner.","You turning left the corner."],0,"Instrução direta usa verbo base: turn."],["Across from significa:",["em frente/do outro lado de","dentro de","antes de chegar a"],0,"Across from situa algo do outro lado, em frente a um marco."],["Complete: “The café is ___ the bank and the park.”",["between","past","through"],0,"Between conecta dois marcos com and."],["Como perguntar se o local fica longe?",["Is it far from here?","Does it far here?","Far is from where it?"],0,"Com be, inverta is e sujeito: Is it…?" ]],"First, go ____. Then turn ____ at ____. It’s ____ from ____.") ,
S("explaining-what-happened","It stopped working","Conte como um objeto deixou de funcionar.","Narrar uma falha simples, indicar momento e sequência de ações, e pedir assistência técnica básica.",12,"Simple past: sequência e verbos de falha","Um telefone deixa de carregar durante uma viagem. Explique o que aconteceu, o que você tentou e o resultado. Descreva observações, não causas que você não confirmou.",[["It stopped working this morning.","Parou de funcionar esta manhã.","Stopped é passado regular; período está definido."],["I plugged it in, but nothing happened.","Conectei à tomada, mas nada aconteceu.","Plug in é verbo frasal; happened é passado de happen."],["Then I tried a different cable.","Depois tentei outro cabo.","Tried é passado de try: y muda para i antes de -ed."],["Could someone take a look at it?","Alguém poderia dar uma olhada?","Take a look at é expressão para examinar." ]],"Relate evento e tentativa no passado","Use simple past para ações concluídas. Conecte etapas com first, then e but. Verbos regulares recebem -ed com ajustes ortográficos (try → tried); verbos irregulares mudam (break → broke). Para pedir ajuda, use Could someone…? ou Could you…?; não conclua a causa sem evidência.",[["The screen broke after the update.","A tela quebrou depois da atualização."],["I restarted the computer, but it didn’t help.","Reiniciei o computador, mas não adiantou."],["She tried another charger.","Ela tentou outro carregador."],["Could you check the connection?","Poderia verificar a conexão?" ]],[["Passado de try:",["tried","tryed","trieded"],0,"Try muda y para i antes de -ed: tried."],["Complete: “I ___ the laptop, but it didn’t start.”",["restarted","restart","restarting"],0,"Ação concluída passada usa restarted."],["Break no passado é:",["broke","breaked","brokened"],0,"Break é irregular: break → broke."],["Qual frase evita presumir a causa?",["The screen stopped working after the update.","The update definitely destroyed everything.","The laptop is always broken because of the user."],0,"Relate o que observou e quando; não atribua causa sem confirmação." ]],"This ____ stopped working ____. First, I ____. Then I ____, but ____. Could you ____?") ,
S("a2-practical-review","A day of errands","Resolva uma sequência de tarefas fora de casa.","Simular três tarefas com pedido de serviço, pergunta de percurso e relato de problema usando tempos e fórmulas adequados.",14,"Revisão integrada de serviços e passado","Você precisa retirar um pacote, marcar um horário e explicar um objeto com defeito. Escolha frases que mantenham a conversa clara, confirmem informações importantes e respeitem que políticas e serviços variam.",[["I’m here to collect a package.","Estou aqui para retirar uma encomenda.","I’m here to + verbo explica propósito."],["Could you tell me which counter I need?","Poderia dizer de qual balcão preciso?","Pedido cortês com pergunta indireta."],["I booked an appointment for Thursday.","Marquei um horário para quinta-feira.","Booked é passado regular; for + dia/data pode indicar agendamento."],["The device stopped working yesterday.","O aparelho parou de funcionar ontem.","Simple past com yesterday." ]],"Escolha estrutura conforme a tarefa","Para finalidade atual, I’m here to…; para pedido, Could you…?; para rotina/serviço, perguntas do/does; para fato concluído com data, simple past; para situação ainda pendente até agora, present perfect + yet. Repita horário, valor ou endereço para confirmar.",[["Could you show me where the post office is?","Poderia me mostrar onde fica o correio?"],["I haven’t received the message yet.","Ainda não recebi a mensagem."],["Does Friday morning work for you?","Sexta de manhã funciona para você?"],["I paid for it yesterday.","Paguei por isso ontem." ]],[["Qual frase explica propósito de visita?",["I’m here to collect a package.","I here collect package.","I’m here collect package to."],0,"I’m here to + verbo descreve o motivo da visita."],["Complete: “I ___ it yesterday.”",["paid for","have pay for","paying for"],0,"Yesterday pede simple past; pay é irregular (paid)."],["Qual pergunta verifica disponibilidade?",["Does Friday work for you?","Do Friday works for you?","Is Friday work you?"],0,"Does + sujeito singular + verbo base work."],["Qual forma significa ainda não recebi até agora?",["I haven’t received it yet.","I didn’t received it yet.","I haven’t receive yesterday."],0,"Present perfect negativo + yet indica expectativa pendente." ]],"I’m here to ____. Could you ____? I ____ yesterday / haven’t ____ yet. Does ____ work?")
]},
{ id:"people-community",title:"Pessoas e comunidade",subtitle:"Descreva relações, lugares e acontecimentos de sua comunidade.",lessons:[
S("describing-people","A friend of mine","Descreva alguém usando adjetivos comuns.","Descrever uma pessoa conhecida com dois adjetivos de personalidade e uma informação contextual respeitosa.",11,"Adjetivos de personalidade e ordem de palavras","Ao apresentar um amigo, você pode falar de interesses e qualidades que observa. Use adjetivos positivos ou neutros, evite rótulos definitivos e dê um exemplo simples que explique sua descrição.",[["She’s a thoughtful friend.","Ela é uma amiga atenciosa.","Adjetivo geralmente vem antes do substantivo; após be também pode vir depois."],["He’s patient with new students.","Ele é paciente com alunos novos.","Patient descreve uma qualidade; with introduz contexto."],["A friend of mine lives nearby.","Uma amiga minha mora perto.","A friend of mine é estrutura comum de posse."],["We get along well.","Nós nos damos bem.","Get along é expressão para relação harmoniosa." ]],"Be + adjetivo; adjetivo + substantivo","Use be + adjective: She is kind. Antes de substantivo, o adjetivo geralmente o precede: a kind person. Adjetivos em inglês não mudam no plural nem por gênero. Use a friend of mine para “um amigo meu”; não *a my friend*. Descreva ações observáveis em vez de generalizações sobre grupos.",[["They are reliable coworkers.","Eles são colegas confiáveis."],["My neighbor is very helpful.","Meu vizinho é muito prestativo."],["A friend of hers works nearby.","Uma amiga dela trabalha perto."],["He’s quiet, but he enjoys meeting people.","Ele é quieto, mas gosta de conhecer pessoas." ]],[["Qual posição do adjetivo está correta?",["a patient teacher","a teacher patient","patient a teacher"],0,"Antes de substantivo, o adjetivo costuma vir antes: a patient teacher."],["Complete: “My friends ___ helpful.”",["are","is","am"],0,"Friends é plural; use are."],["“A friend of mine” significa:",["um amigo meu","um amigo de mim (incorreto em inglês)","meu amigo de amigo"],0,"A friend of mine é a forma natural de posse."],["Qual descrição usa adjetivo sem generalizar?",["My cousin is patient with children.","Everyone from that city is impatient.","All neighbors are the same."],0,"Descreva uma pessoa/situação específica, não um grupo inteiro." ]],"A friend of mine is ____. They’re a ____ person because ____. We ____ together.") ,
S("getting-along","We get along well","Fale de relações e atividades em comum.","Falar de afinidades e diferenças em uma relação usando enjoy, both e contraste simples.",11,"Afinidades, both e enjoy + -ing","Pessoas próximas podem compartilhar interesses e também gostar de coisas diferentes. Pratique falar de atividades em comum e preferências sem sugerir que uma boa relação exige concordância em tudo.",[["We both enjoy cooking.","Nós dois gostamos de cozinhar.","Both vem após sujeito/pronome e antes do verbo principal."],["I get along well with my sister.","Eu me dou bem com minha irmã.","Get along with + pessoa."],["He likes hiking, but I prefer cycling.","Ele gosta de trilhas, mas prefiro ciclismo.","But conecta preferências contrastantes."],["We don’t always agree.","Nem sempre concordamos.","Not always significa nem sempre; é diferente de never." ]],"Both e enjoy + verbo em -ing","Use both + verbo para indicar algo que duas pessoas fazem: We both like… . Com enjoy, o próximo verbo geralmente recebe -ing: enjoy reading. Get along with identifica com quem a relação funciona. Use but para contraste; differences are normal e não significam conflito automaticamente.",[["They both work near the station.","Os dois trabalham perto da estação."],["I enjoy spending time with my cousins.","Gosto de passar tempo com meus primos."],["We get along, although we have different hobbies.","Nos damos bem, embora tenhamos hobbies diferentes."],["She enjoys music, but her partner prefers books.","Ela gosta de música, mas sua parceira prefere livros." ]],[["Complete: “We both ___ music.”",["enjoy","enjoys","enjoying"],0,"Com sujeito we, use enjoy sem -s."],["Após enjoy, use:",["verbo em -ing","to + verbo","verbo no passado"],0,"Enjoy é seguido por gerúndio: enjoy reading."],["Qual preposição segue get along?",["with","at","for"],0,"Get along with someone significa se dar bem com alguém."],["“We don’t always agree” significa:",["Nem sempre concordamos.","Nunca conversamos.","Concordamos sempre."],0,"Don’t always indica que nem sempre acontece, não que nunca ocorre." ]],"We both enjoy ____. I get along well with ____, but we don’t always ____.") ,
S("community-places","A place near home","Descreva serviços e espaços de um bairro.","Descrever a localização de três espaços comunitários e dizer o que é possível fazer neles.",12,"Lugares, relative clauses simples e localização","Um guia de bairro ajuda alguém novo a se orientar. Apresente lugares e o serviço que oferecem, usando referências de localização e frases curtas que distingam fato de preferência pessoal.",[["There’s a library across from the park.","Há uma biblioteca em frente ao parque.","There’s apresenta lugar singular; across from indica localização."],["The clinic is next to the pharmacy.","A clínica fica ao lado da farmácia.","Next to significa ao lado de."],["It’s a place where people can read.","É um lugar onde as pessoas podem ler.","Where introduz informação sobre o lugar."],["The market is busy on Saturday mornings.","O mercado fica movimentado nas manhãs de sábado.","On Saturday mornings indica momento recorrente." ]],"Descreva lugar, posição e função","Use there is/are para apresentar existência; next to, across from e between para localização. Acrescente função com where + sujeito + verbo: a place where people meet. Use can + verbo base para possibilidade. There is/are concorda com o nome que vem em seguida.",[["There are two cafés near the station.","Há dois cafés perto da estação."],["The square is between the bank and the museum.","A praça fica entre o banco e o museu."],["It’s a center where children can play.","É um centro onde crianças podem brincar."],["The bus stop is in front of the library.","O ponto de ônibus fica em frente à biblioteca." ]],[["Complete: “There ___ a clinic next to the park.”",["is","are","be"],0,"A clinic é singular; use there is."],["Between é usado com:",["dois pontos de referência","um horário exato","uma pessoa apenas"],0,"Between A and B situa algo entre dois marcos."],["Qual frase explica função de um lugar?",["It’s a place where people can study.","It’s where place people study can.","It place people studying."],0,"Where introduz a oração que descreve o lugar."],["After can, use:",["verbo base","verbo + -s","to + verbo"],0,"Can é seguido por verbo base: can study." ]],"There’s a ____ next to/across from ____. It’s a place where people can ____.") ,
S("invitations-and-events","Are you coming?","Responda a convites para eventos e celebrações.","Convidar, aceitar ou recusar um convite e combinar detalhes práticos de um evento.",12,"Convites com would like, can e respostas corteses","Uma vizinha convida você para uma feira comunitária. Pratique aceitar com entusiasmo, recusar sem inventar justificativas detalhadas e perguntar sobre horário ou o que levar.",[["Would you like to come to the festival?","Você gostaria de vir ao festival?","Would you like to + verbo faz convite cortês."],["I’d love to. What time does it start?","Adoraria. Que horas começa?","I’d love to aceita com entusiasmo."],["I’m sorry, I can’t make it this time.","Sinto muito, não vou conseguir desta vez.","Can’t make it significa não conseguir comparecer."],["Would you like me to bring something?","Você gostaria que eu trouxesse algo?","Would you like me to + verbo oferece ajuda." ]],"Aceite, recuse e confirme detalhes","Convide com Would you like to…? Aceite com I’d love to / That sounds great. Recuse brevemente com I’m sorry, I can’t make it. Pergunte What time does it start? para horário; com evento singular, does + verbo base. Não é preciso justificar além do que deseja compartilhar.",[["Would you like to join us for dinner?","Gostaria de se juntar a nós para jantar?"],["That sounds lovely. Where should we meet?","Parece ótimo. Onde devemos nos encontrar?"],["Can I bring a friend?","Posso levar um amigo?"],["Thanks for inviting me.","Obrigado(a) pelo convite." ]],[["Qual frase é um convite?",["Would you like to come to the event?","You come event would?","Would you coming event?"],0,"Would you like to + verbo base faz convite."],["Responda aceitando:",["I’d love to. What time does it start?","I love to yesterday start.","I’d love coming at start."],0,"I’d love to aceita; a pergunta usa does + start."],["Como recusar gentilmente?",["I’m sorry, I can’t make it this time.","No. Never invite me.","I can’t to make this."],0,"A primeira frase é cortês e clara sem ser excessiva."],["Complete: “What time ___ the event start?”",["does","do","is"],0,"Event singular pede does; start fica na forma base." ]],"Would you like to ____? I’d love to / I’m sorry, I can’t ____. What time does it start?") ,
S("people-review","People around us","Junte descrições de pessoas, lugares e relações.","Apresentar duas pessoas e um lugar comunitário, conectando descrição, afinidade e localização em um parágrafo curto.",13,"Revisão: descrição, relações e comunidade","Esta revisão reúne pessoas, relações e lugares. Escolha detalhes respeitosos sobre quem participa da comunidade, indique uma atividade compartilhada e situe um local importante para evitar descrições genéricas.",[["My neighbor Ana is friendly and practical.","Minha vizinha Ana é simpática e prática.","Be + adjetivos descreve características observadas."],["She volunteers at the community garden.","Ela faz trabalho voluntário na horta comunitária.","Volunteers é simple present com she."],["We both enjoy sharing vegetables.","Nós duas gostamos de compartilhar vegetais.","Both e enjoy + -ing expressam atividade em comum."],["The garden is behind the library.","A horta fica atrás da biblioteca.","Behind indica localização atrás de um marco." ]],"Una pessoa, ação e lugar","Use be + adjetivo para descrever; simple present para rotina; both + verbo para experiência comum; enjoy + -ing para atividade; e preposições de lugar para orientar. Conecte com and/but. Prefira exemplos específicos e evite afirmar que uma pessoa representa toda uma comunidade.",[["My friends are helpful, and they live nearby.","Meus amigos são prestativos e moram perto."],["We both enjoy going to the local market.","Nós dois gostamos de ir ao mercado local."],["The center is across from the station.","O centro fica em frente à estação."],["It’s a place where neighbors can meet.","É um lugar onde vizinhos podem se encontrar." ]],[["Complete: “My neighbors ___ friendly.”",["are","is","am"],0,"Neighbors está no plural; use are."],["Qual forma vem após enjoy?",["meeting","meet","to meeting"],0,"Enjoy + verbo em -ing: enjoy meeting."],["Qual frase localiza corretamente?",["The garden is behind the library.","The garden behind is library.","The garden is behind to library."],0,"Behind + lugar indica que fica atrás do marco."],["Qual texto evita generalização?",["My neighbor helps organize the monthly market.","Everyone in town has the same interests.","All neighbors are always friendly."],0,"A frase descreve uma ação específica de uma pessoa." ]],"My ____ is ____. They ____. We both enjoy ____. The ____ is ____ the ____.") ,
S("moving-house","A new place to live","Descreva opções simples de moradia.","Comparar duas opções de moradia usando there is/are, comparativos e linguagem de preferência.",12,"Moradia, comparativos e preferência","Uma mudança envolve comparar localização, espaço e acesso a serviços. Pratique descrever opções com informações simples; custos e condições reais precisam ser confirmados diretamente com o responsável pelo imóvel.",[["This apartment is closer to the station.","Este apartamento fica mais perto da estação.","Closer é comparativo de close."],["There are two bedrooms and a small balcony.","Há dois quartos e uma varanda pequena.","There are concorda com nomes plurais."],["The rent is lower, but the bus is less frequent.","O aluguel é menor, mas o ônibus é menos frequente.","Lower/less frequent comparam aspectos."],["I’d prefer the quieter neighborhood.","Eu preferiria o bairro mais tranquilo.","Would prefer apresenta preferência de forma suave." ]],"Comparar alternativas de moradia","Adjetivos curtos geralmente usam -er + than (closer than); alguns usam more + adjetivo (more convenient than). Less + adjetivo expressa menor grau. Use there is com singular/incontável e there are com plural. Prefira apresentar critérios pessoais e verificar valores, contrato e disponibilidade com fontes responsáveis.",[["The second room is bigger than the first.","O segundo quarto é maior que o primeiro."],["This area is more convenient for work.","Esta área é mais conveniente para o trabalho."],["There is a bus stop nearby.","Há um ponto de ônibus por perto."],["We’d prefer a place with more sunlight.","Preferiríamos um lugar com mais luz solar." ]],[["Comparativo de close:",["closer","more close","closest than"],0,"Close normalmente forma closer + than."],["Complete: “There ___ three rooms.”",["are","is","be"],0,"Three rooms é plural; use there are."],["Qual frase compara duas opções?",["This apartment is quieter than the other one.","This apartment quiet than other.","This apartment is more quieter."],0,"Quieter + than compara; não use dupla marca comparativa."],["O que deve ser confirmado antes de alugar?",["Condições e valores diretamente com fonte responsável.","Suposições com base em uma frase de exemplo.","Dados bancários enviados por mensagem desconhecida."],0,"A aula pratica idioma; condições reais exigem confirmação segura." ]],"This place is ____ than ____. There is/are ____. I’d prefer ____ because ____.") ,
S("sharing-a-home","Whose turn is it?","Combine tarefas domésticas e responsabilidades.","Combinar uma divisão simples de tarefas domésticas usando possessivos, whose e propostas com let’s.",12,"Possessivos, whose e tarefas","Dividir tarefas com clareza ajuda colegas de casa a combinar responsabilidades. Use perguntas neutras sobre de quem é um objeto e propostas práticas para organizar a próxima tarefa, sem atribuir papéis fixos às pessoas.",[["Whose turn is it to do the dishes?","De quem é a vez de lavar a louça?","Whose pergunta de quem; it’s your turn to… indica a vez."],["It’s my turn to take out the bins.","É minha vez de levar o lixo para fora.","My é possessivo; turn to + verbo marca tarefa."],["Let’s make a simple schedule.","Vamos fazer um cronograma simples.","Let’s + verbo base sugere ação conjunta."],["Is this your key or mine?","Esta chave é sua ou minha?","Mine substitui my key; não precisa repetir o nome." ]],"Whose e pronomes possessivos","Use whose + substantivo para perguntar a quem algo pertence: Whose mug is this? Use my/your/his/her/our antes do nome; mine/yours/his/hers/ours aparecem sem nome. Para organizar tarefa, use It’s my/your turn to + verbo. Proponha com Let’s + verbo base.",[["Whose coat is this? It’s hers.","De quem é este casaco? É dela."],["Our turn is to clean the kitchen.","Nossa vez é de limpar a cozinha."],["Is that your charger or mine?","Aquele carregador é seu ou meu?"],["Let’s take turns cooking dinner.","Vamos nos revezar para preparar o jantar." ]],[["Complete: “Whose ___ is this?”",["mug","my","mine"],0,"Whose pode vir antes do substantivo mug."],["Qual forma substitui “my key”?",["mine","my","I"],0,"Mine é pronome possessivo usado sem substantivo."],["Após Let’s, use:",["verbo base","to + verbo","verbo com -s"],0,"Let’s + verbo base: Let’s make."],["“It’s your turn to…” introduz:",["uma tarefa que cabe a você agora","um lugar distante","uma pergunta sobre ontem"],0,"Your turn indica de quem é a vez/responsabilidade combinada." ]],"Whose ____ is this? It’s mine/yours. It’s ____ turn to ____. Let’s ____ together.") ,
S("community-events","What’s happening this week?","Descubra eventos e atividades locais.","Perguntar sobre eventos, dia, horário e local, compreendendo anúncios simples da comunidade.",12,"Present continuous futuro combinado e perguntas","Um centro comunitário publica atividades da semana. Aprenda a perguntar o que está acontecendo e a interpretar horário e local; confirme mudanças em canais oficiais do organizador.",[["What’s happening at the center this week?","O que está acontecendo no centro esta semana?","What’s happening pergunta por evento/atividade atual ou planejada."],["The market is opening on Saturday.","A feira vai abrir no sábado.","Present continuous pode expressar plano futuro organizado."],["The workshop starts at six.","A oficina começa às seis.","Simple present também anuncia horário fixo programado."],["Where is the meeting taking place?","Onde será a reunião?","Take place significa acontecer; present continuous descreve programação." ]],"Falar de eventos programados","Use present continuous para planos organizados: We’re meeting on Friday. Horários públicos também usam simple present: The event starts at six. Pergunte What time does it start? e Where is it taking place? Distinga anúncio de confirmação: consulte o organizador para alterações.",[["We’re visiting the community garden tomorrow.","Vamos visitar a horta comunitária amanhã."],["The film begins at 7 p.m.","O filme começa às 19h."],["Are they holding a class this week?","Eles vão oferecer uma aula esta semana?"],["The meeting is taking place in Room 4.","A reunião está acontecendo na sala 4." ]],[["Qual frase indica um plano combinado?",["We’re meeting the organizer tomorrow.","We meet yesterday tomorrow.","We are meet the organizer."],0,"Present continuous: are + verbo-ing pode indicar arranjo futuro."],["Pergunte o horário de início:",["What time does it start?","What time it starts does?","When time start it?"],0,"Simple present pergunta com does + sujeito + verbo base."],["Take place significa:",["acontecer","levar para casa","pagar"],0,"Take place significa ocorrer/acontecer."],["O que fazer se o evento pode ter sido alterado?",["Confirmar com o organizador/canal oficial.","Assumir que nunca muda.","Usar uma data inventada."],0,"Informações atuais devem ser confirmadas com a fonte do evento." ]],"What’s happening ____? The event starts at ____. We’re meeting ____ at ____.") ,
S("being-a-good-neighbor","A helpful neighbor","Faça pedidos e ofereça ajuda na vizinhança.","Fazer um pedido comunitário cortês e oferecer ajuda com can/could e respostas adequadas.",12,"Ofertas e pedidos com can/could","Uma vizinha está carregando caixas e você pode oferecer ajuda. Pratique oferecer sem presumir que a pessoa precisa, aceitar ou recusar com cordialidade e fazer pedidos claros respeitando limites e privacidade.",[["Would you like a hand?","Quer uma ajuda?","Would you like…? oferece sem impor."],["Could you hold the door, please?","Poderia segurar a porta, por favor?","Could you + verbo base é pedido cortês."],["I can carry one box.","Posso carregar uma caixa.","Can + base expressa capacidade/oferta."],["That’s kind of you, but I’m okay.","Que gentileza, mas estou bem.","Resposta natural para agradecer e recusar." ]],"Oferecer ajuda e respeitar a resposta","Ofereça com Would you like…? ou Can I help?; faça pedido com Could you…? A resposta pode aceitar: Yes, please; recusar: No, thank you, I’m fine. Use could para cortesia; can também é comum em contextos informais. Não insista se a pessoa recusar.",[["Can I help you carry those bags?","Posso ajudar a carregar essas bolsas?"],["Would you like me to call the building manager?","Quer que eu ligue para a administração do prédio?"],["Could you let me know when you’re home?","Poderia me avisar quando estiver em casa?"],["Thanks, but I can manage.","Obrigado(a), mas consigo me virar." ]],[["Qual frase oferece ajuda sem impor?",["Would you like a hand?","I will carry everything now.","You need my help."],0,"Would you like…? deixa a decisão com a outra pessoa."],["Complete: “Could you ___ the door?”",["hold","holds","to hold"],0,"Após could, use verbo base."],["Como recusar com gentileza?",["Thanks, but I’m okay.","No, you are bad.","I don’t can help."],0,"A frase agradece e recusa respeitosamente."],["Se a pessoa recusa a ajuda, é melhor:",["respeitar a resposta","insistir repetidamente","entrar sem permissão"],0,"Respeitar o limite mantém a interação cordial." ]],"Would you like ____? I can ____. Could you ____? Thanks, but ____.") ,
S("first-then-finally","First, then, finally","Ordene eventos usando conectores de sequência.","Organizar uma história curta em quatro etapas usando conectores de sequência e verbos no passado.",12,"Conectores first, then, after that, finally","Uma boa história ajuda quem ouve a acompanhar a ordem dos acontecimentos. Relembre um passeio simples e organize os eventos em uma sequência clara, escolhendo conectores que indiquem começo, continuidade e conclusão.",[["First, we bought the tickets.","Primeiro, compramos os ingressos.","First apresenta o primeiro evento; bought é passado de buy."],["Then we took the train.","Depois pegamos o trem.","Then liga o próximo evento; took é passado de take."],["After that, we walked to the museum.","Depois disso, caminhamos até o museu.","After that explicita a ordem seguinte."],["Finally, we got home before dinner.","Por fim, chegamos em casa antes do jantar.","Finally marca o último evento; got é passado de get." ]],"Marque a ordem sem repetir conectores em excesso","First, then, after that e finally ajudam a guiar uma narrativa. Use simple past para eventos concluídos. O conector normalmente vem no início da frase e pode ser seguido de vírgula. Não é obrigatório usar todos; escolha os que tornam a sequência clara.",[["First, I checked the map.","Primeiro, olhei o mapa."],["Then we found the bus stop.","Depois encontramos o ponto de ônibus."],["After that, we visited the market.","Depois disso, visitamos o mercado."],["Finally, we had lunch together.","Por fim, almoçamos juntos." ]],[["Qual conector costuma abrir uma sequência?",["First","Finally","Last year"],0,"First introduz o primeiro passo ou evento."],["Complete: “Then we ___ the bus.”",["caught","catch","catches"],0,"Caught é passado irregular de catch."],["Qual opção indica um evento posterior?",["After that, we visited the museum.","Before that, we visit tomorrow.","At that, visited we museum."],0,"After that conecta o evento seguinte na narrativa."],["Qual frase conclui a sequência?",["Finally, we got home.","First, we left.","Tomorrow, we go."],0,"Finally sinaliza o fechamento da sequência." ]],"First, I ____. Then, we ____. After that, ____. Finally, ____.") ,
S("a2-community-project","My neighborhood guide","Crie uma descrição curta de um lugar da comunidade.","Produzir um mini-guia oral/escrito de um lugar comunitário com localização, função, evento e convite/informação prática.",15,"Projeto integrador A2: descrição e informação comunitária","Neste projeto, escolha um espaço público ou serviço comunitário real ou fictício. Apresente sua localização, explique o que as pessoas podem fazer ali e inclua um evento ou horário como exemplo. Se usar dados reais, confirme-os antes de compartilhar.",[["There’s a small library near the river.","Há uma pequena biblioteca perto do rio.","There’s apresenta lugar singular; near indica proximidade."],["It’s a place where people can read and study.","É um lugar onde as pessoas podem ler e estudar.","Where introduz a função do local."],["They’re holding a book exchange next Saturday.","Vão realizar uma troca de livros no próximo sábado.","Present continuous pode indicar evento organizado."],["Would you like to visit with me?","Você gostaria de visitar comigo?","Would you like to + verbo faz convite." ]],"Organize um mini-guia em blocos","Apresente o lugar com there is/are; localize com next to, near, across from; explique função com where + oração; informe evento usando present continuous para arranjo ou simple present para horário oficial; encerre com convite. Separe informação confirmada de sugestão pessoal e não publique dados privados de terceiros.",[["The center is across from the bus station.","O centro fica em frente à rodoviária."],["People can join a free reading group there.","As pessoas podem participar de um grupo de leitura gratuito lá."],["The group meets every Wednesday at 5 p.m.","O grupo se reúne toda quarta às 17h."],["Would you like to come along?","Você gostaria de vir junto?" ]],[["Qual frase apresenta corretamente um lugar?",["There’s a community center near the park.","There are a center near park.","A center there near is park."],0,"A community center é singular; use there’s/there is."],["Qual frase explica a função do espaço?",["It’s a place where people can meet.","It’s a where place people meet.","It place meets people."],0,"Where introduz informação sobre o lugar."],["Um horário oficial recorrente costuma usar:",["The group meets every Wednesday at five.","The group meet yesterday at five.","The group is meet every Wednesday."],0,"Simple present pode expressar programação/horário estabelecido."],["Antes de publicar horário atual, você deve:",["confirmar com fonte responsável","inventar para completar o texto","divulgar endereço residencial de alguém"],0,"O projeto separa exemplo de dado real; confirme informações e proteja privacidade." ]],"Welcome to ____. It’s ____ near ____. People can ____. ____ meets ____. Would you like to ____?")
]}
];

export const a2ContinuationLessons: Lesson[] = a2ContinuationModules.flatMap((module) => module.lessons);
